package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.Map;
import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class BookDiscardIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void discarding_an_available_book_marks_it_as_discarded() throws Exception {
        String bookId = registerBook("훼손된 책");

        mockMvc.perform(post("/books/{bookId}/discard", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.id").value(bookId))
                .andExpect(jsonPath("$.title").value("훼손된 책"))
                .andExpect(jsonPath("$.status").value("DISCARDED"));
    }

    @Test
    void discarding_a_book_on_loan_returns_409() throws Exception {
        String bookId = registerBook("대출 중 폐기 시도");
        loanBook(bookId, registerMember("백지훈"));

        mockMvc.perform(post("/books/{bookId}/discard", bookId))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_ON_LOAN"));
    }

    @Test
    void discarding_a_book_after_it_is_returned_succeeds() throws Exception {
        String bookId = registerBook("반납 후 폐기");
        String loanId = loanBook(bookId, registerMember("송다은"));

        mockMvc.perform(post("/loans/{loanId}/return", loanId))
                .andExpect(status().isOk());

        mockMvc.perform(post("/books/{bookId}/discard", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("DISCARDED"));
    }

    @Test
    void loaning_a_discarded_book_returns_409() throws Exception {
        String bookId = registerBook("폐기 후 대출 시도");
        String memberId = registerMember("노시우");

        mockMvc.perform(post("/books/{bookId}/discard", bookId))
                .andExpect(status().isOk());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(Map.of("bookId", bookId, "memberId", memberId))))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_DISCARDED"));
    }

    @Test
    void discarding_an_unknown_book_returns_404() throws Exception {
        mockMvc.perform(post("/books/{bookId}/discard", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    private String loanBook(String bookId, String memberId) throws Exception {
        String response = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(Map.of("bookId", bookId, "memberId", memberId))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(response).get("loanId").asText();
    }

    private String registerBook(String title) throws Exception {
        String response = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        JsonNode book = objectMapper.readTree(response);
        return book.get("id").asText();
    }

    private String registerMember(String name) throws Exception {
        String response = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"" + name + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(response).get("memberId").asText();
    }
}
