package com.example.lending.domain;

import java.util.List;
import java.util.UUID;

// 한 책의 소진되지 않은 예약 줄. 맨 앞이 가장 먼저 예약한 사람이다
public class ReservationQueue {

    private final UUID bookId;
    private final List<Reservation> active;

    public ReservationQueue(UUID bookId, List<Reservation> activeInOrder) {
        this.bookId = bookId;
        this.active = List.copyOf(activeInOrder);
    }

    public int size() {
        return active.size();
    }

    public void ensureNotReservedBy(UUID memberId) {
        if (active.stream().anyMatch(reservation -> reservation.getMemberId().equals(memberId))) {
            throw new AlreadyReservedException(bookId, memberId);
        }
    }

    // 예약이 있으면 맨 앞 예약자만 빌릴 수 있다
    public void ensureLoanableBy(UUID memberId) {
        if (active.isEmpty()) {
            return;
        }
        if (!active.get(0).getMemberId().equals(memberId)) {
            throw new ReservedForOtherException(bookId);
        }
    }

    public Optional<Reservation> front() {
        return active.isEmpty() ? Optional.empty() : Optional.of(active.get(0));
    }

    public List<QueuedReservation> entries() {
        return IntStream.range(0, active.size())
                .mapToObj(i -> new QueuedReservation(active.get(i).getId(), active.get(i).getMemberId(), i + 1))
                .toList();
    }
}
