package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.Map;
import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class ReservationIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void reserving_an_available_book_returns_409() throws Exception {
        String bookId = registerBook("예약 불가 - 대출 가능한 책");

        reserve(bookId, registerMember("서하린"))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_AVAILABLE"));
    }

    @Test
    void reserving_a_discarded_book_returns_409() throws Exception {
        String bookId = registerBook("예약 불가 - 폐기된 책");
        mockMvc.perform(post("/books/{bookId}/discard", bookId)).andExpect(status().isOk());

        reserve(bookId, registerMember("진유찬"))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_DISCARDED"));
    }

    @Test
    void reserving_an_unknown_book_returns_404() throws Exception {
        reserve(UUID.randomUUID().toString(), registerMember("권민서"))
                .andExpect(status().isNotFound());
    }

    @Test
    void reservations_form_a_queue_in_order() throws Exception {
        String bookId = registerBook("줄 서는 책");
        loanBook(bookId, registerMember("대여자"));

        reserve(bookId, registerMember("첫째"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.position").value(1));
        reserve(bookId, registerMember("둘째"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.position").value(2));
    }

    @Test
    void same_member_cannot_reserve_the_same_book_twice() throws Exception {
        String bookId = registerBook("중복 예약 책");
        loanBook(bookId, registerMember("대여자2"));
        String memberId = registerMember("중복자");

        reserve(bookId, memberId).andExpect(status().isCreated());
        reserve(bookId, memberId)
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("ALREADY_RESERVED"));
    }

    @Test
    void listing_reservations_returns_the_queue_in_order() throws Exception {
        String bookId = registerBook("목록 조회 책");
        loanBook(bookId, registerMember("대여자3"));
        String firstMemberId = registerMember("목록 첫째");
        String secondMemberId = registerMember("목록 둘째");
        String firstReservationId = reservationIdOf(reserve(bookId, firstMemberId));
        String secondReservationId = reservationIdOf(reserve(bookId, secondMemberId));

        mockMvc.perform(get("/books/{bookId}/reservations", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(2))
                .andExpect(jsonPath("$[0].reservationId").value(firstReservationId))
                .andExpect(jsonPath("$[0].memberId").value(firstMemberId))
                .andExpect(jsonPath("$[0].position").value(1))
                .andExpect(jsonPath("$[1].reservationId").value(secondReservationId))
                .andExpect(jsonPath("$[1].memberId").value(secondMemberId))
                .andExpect(jsonPath("$[1].position").value(2));
    }

    @Test
    void listing_reservations_of_an_unknown_book_returns_404() throws Exception {
        mockMvc.perform(get("/books/{bookId}/reservations", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    @Test
    void after_return_only_the_first_reserver_can_loan() throws Exception {
        String bookId = registerBook("순서대로 빌리는 책");
        String loanId = loanBook(bookId, registerMember("반납자"));
        String firstMemberId = registerMember("순서 첫째");
        String secondMemberId = registerMember("순서 둘째");
        reserve(bookId, firstMemberId).andExpect(status().isCreated());
        reserve(bookId, secondMemberId).andExpect(status().isCreated());

        mockMvc.perform(post("/loans/{loanId}/return", loanId)).andExpect(status().isOk());

        loan(bookId, secondMemberId)
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("RESERVED_FOR_OTHER"));
        loan(bookId, firstMemberId).andExpect(status().isCreated());
    }

    @Test
    void after_the_first_reserver_borrows_the_next_reserver_becomes_first() throws Exception {
        String bookId = registerBook("예약 소진 후 다음 순번");
        String loanId = loanBook(bookId, registerMember("이전 대여자"));
        String firstMemberId = registerMember("소진 첫째");
        String secondMemberId = registerMember("소진 둘째");
        reserve(bookId, firstMemberId).andExpect(status().isCreated());
        reserve(bookId, secondMemberId).andExpect(status().isCreated());
        mockMvc.perform(post("/loans/{loanId}/return", loanId)).andExpect(status().isOk());
        loan(bookId, firstMemberId).andExpect(status().isCreated());

        // 소진된 예약은 목록에서 빠지고, 다음 사람이 맨 앞이 된다
        mockMvc.perform(get("/books/{bookId}/reservations", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].memberId").value(secondMemberId))
                .andExpect(jsonPath("$[0].position").value(1));

        String thirdLoanId = null;
        mockMvc.perform(post("/loans/{loanId}/return", loanIdOf(bookId, firstMemberId)))
                .andExpect(status().isOk());
        loan(bookId, secondMemberId).andExpect(status().isCreated());
    }

    @Test
    void book_without_reservations_can_be_loaned_by_anyone_after_return() throws Exception {
        String bookId = registerBook("예약 없는 책");
        String loanId = loanBook(bookId, registerMember("예약 없는 대여자"));
        mockMvc.perform(post("/loans/{loanId}/return", loanId)).andExpect(status().isOk());

        loan(bookId, registerMember("아무나")).andExpect(status().isCreated());
    }

    private org.springframework.test.web.servlet.ResultActions reserve(String bookId, String memberId)
            throws Exception {
        return mockMvc.perform(post("/books/{bookId}/reservations", bookId)
                .contentType(MediaType.APPLICATION_JSON)
                .content(objectMapper.writeValueAsString(Map.of("memberId", memberId))));
    }

    private org.springframework.test.web.servlet.ResultActions loan(String bookId, String memberId)
            throws Exception {
        return mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                .content(objectMapper.writeValueAsString(Map.of("bookId", bookId, "memberId", memberId))));
    }

    private String reservationIdOf(org.springframework.test.web.servlet.ResultActions result) throws Exception {
        String response = result.andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(response).get("reservationId").asText();
    }

    private String loanIdOf(String bookId, String memberId) throws Exception {
        String response = loan(bookId, memberId).andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(response).get("loanId").asText();
    }

    private String loanBook(String bookId, String memberId) throws Exception {
        return loanIdOf(bookId, memberId);
    }

    private String registerBook(String title) throws Exception {
        String response = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        JsonNode book = objectMapper.readTree(response);
        return book.get("id").asText();
    }

    private String registerMember(String name) throws Exception {
        String response = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"" + name + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(response).get("memberId").asText();
    }
}
